function main(): void {
  const s: string = "12";
  console.log(+s + 1, +"3.5", +"abc");
  const t = "  7 ";
  console.log(+t, +true, +"", +" 0x10 ", +"1e3", +"-5");
  const a: any = "42";
  const arr = ["1", "2"];
  console.log(+a, +arr[1]);
  console.log(["10", "20"].map((x) => +x).reduce((p, c) => p + c, 0));
}
